wxBitmap AppBitmap(int size) {
    wxImage tile(16, 16);
    for (int i = 0; i < 16 * 16; ++i) {
        const unsigned char* p = GOLEM + i * 3;
        tile.SetRGB(i % 16, i / 16, p[0], p[1], p[2]);
    }
    return wxBitmap(tile.Scale(size, size, wxIMAGE_QUALITY_NEAREST));
}

wxIconBundle AppIcons() {
    wxIconBundle icons;
    for (int size : {16, 20, 24, 32, 48, 64, 256}) {
        wxIcon icon;
        icon.CopyFromBitmap(AppBitmap(size));
        icons.AddIcon(icon);
    }
    return icons;
}
